function setEnv(name, value) {
  if (value === undefined) {
    delete process.env[name];
  } else {
    process.env[name] = value;
  }
}
function restoreEnv(snapshot) {
  for (const [name, value] of Object.entries(snapshot)) {
    setEnv(name, value);
  }
}
