async function setupAgentInstructions(projectRoot) {
  console.log(source_default.bold.cyan(`
\uD83E\uDD16 Agent Instructions Setup
`));
  console.log(source_default.gray(`Would you like to add backlog-jira plugin guidelines to your agent instruction files?
`));
  const response = await import_prompts2.default({
    type: "confirm",
    name: "shouldSetup",
    message: "Add plugin guidelines to agent instruction files?",
    initial: true
  });
  if (response.shouldSetup === undefined) {
    logger.info("Setup cancelled.");
    return;
  }
  const shouldSetup = response.shouldSetup;
  if (!shouldSetup) {
    logger.info("Skipping agent instructions setup. You can add them later manually.");
    return;
  }
  const commonAgentFiles = [
    "AGENTS.md",
    "CLAUDE.md",
    "CURSOR.md",
    "AI.md",
    ".cursorrules",
    ".github/AGENTS.md"
  ];
  const existingFiles = commonAgentFiles.map((file) => join10(projectRoot, file)).filter((filePath) => existsSync9(filePath));
  if (existingFiles.length === 0) {
    console.log(source_default.yellow("No agent instruction files found in project root (AGENTS.md, CLAUDE.md, etc.)"));
    console.log(source_default.gray("Create an agent instruction file first, then re-run initialization."));
    return;
  }
  console.log(source_default.green(`
Found ${existingFiles.length} agent instruction file(s):
`));
  const filesResponse = await import_prompts2.default({
    type: "multiselect",
    name: "selectedFiles",
    message: "Select files to update:",
    choices: existingFiles.map((filePath) => ({
      title: filePath.replace(`${projectRoot}/`, ""),
      value: filePath,
      selected: true
    })),
    min: 1,
    instructions: false
  });
  if (filesResponse.selectedFiles === undefined) {
    logger.info("Setup cancelled.");
    return;
  }
  const selectedFiles = filesResponse.selectedFiles;
  if (selectedFiles.length === 0) {
    logger.info("No files selected. Skipping agent instructions setup.");
    return;
  }
  console.log(source_default.cyan(`
Choose how agent instructions should be added:
`));
  console.log(source_default.gray("  CLI Mode: Embeds comprehensive plugin guidelines directly"));
  console.log(source_default.gray(`  MCP Mode: Adds a short nudge to read MCP resources
`));
  const modeResponse = await import_prompts2.default({
    type: "select",
    name: "mode",
    message: "Select instruction mode:",
    choices: [
      {
        title: "CLI Mode - Embedded guidelines (recommended for CLI-only usage)",
        value: "cli",
        description: "Add comprehensive documentation directly to the file"
      },
      {
        title: "MCP Mode - Reference to MCP resources (recommended if using MCP server)",
        value: "mcp",
        description: "Add a short reference to read MCP resources for details"
      }
    ],
    initial: 0
  });
  if (modeResponse.mode === undefined) {
    logger.info("Setup cancelled.");
    return;
  }
  const mode = modeResponse.mode;
  console.log(source_default.cyan(`
Adding ${mode.toUpperCase()} mode instructions to ${selectedFiles.length} file(s)...
`));
  for (const filePath of selectedFiles) {
    const fileName = filePath.replace(`${projectRoot}/`, "");
    const result = addAgentInstructions(filePath, mode);
    if (result.success) {
      console.log(source_default.green(`  ✓ ${fileName}`));
    } else {
      console.log(source_default.red(`  ✗ ${fileName}: ${result.message}`));
    }
  }
  console.log(source_default.green(`
✓ Agent instructions updated successfully in ${mode.toUpperCase()} mode`));
  console.log(source_default.gray("  Guidelines are wrapped with HTML comment markers for easy updates."));
  console.log(source_default.gray("  Re-run 'backlog-jira init' to switch modes or update guidelines."));
  await offerGitCommit(selectedFiles, mode);
}
async function offerGitCommit(files, mode) {
  const { exec } = await import("node:child_process");
  const { promisify } = await import("node:util");
  const execAsync = promisify(exec);
  const projectRoot = files[0] ? join10(files[0], "..") : process.cwd();
  try {
    await execAsync("git rev-parse --git-dir", { cwd: projectRoot });
  } catch {
    return;
  }
  const relativeFiles = files.map((f) => f.replace(`${projectRoot}/`, ""));
  try {
    const { stdout: statusOutput } = await execAsync(`git status --porcelain ${relativeFiles.join(" ")}`, { cwd: projectRoot });
    if (!statusOutput.trim()) {
      return;
    }
    console.log(source_default.cyan(`
\uD83D\uDCBE Git Commit
`));
    const commitResponse = await import_prompts2.default({
      type: "confirm",
      name: "shouldCommit",
      message: "Commit agent instruction changes to git?",
      initial: false
    });
    if (commitResponse.shouldCommit === undefined) {
      return;
    }
    const shouldCommit = commitResponse.shouldCommit;
    if (!shouldCommit) {
      return;
    }
    await execAsync(`git add ${relativeFiles.join(" ")}`, {
      cwd: projectRoot
    });
    const commitMessage = `chore: add backlog-jira ${mode.toUpperCase()} guidelines to agent instructions

Updated files:
${relativeFiles.map((f) => `- ${f}`).join(`
`)}

Mode: ${mode.toUpperCase()}
Added via: backlog-jira init`;
    await execAsync(`git commit -m ${JSON.stringify(commitMessage)}`, {
      cwd: projectRoot
    });
    console.log(source_default.green("✓ Changes committed to git"));
  } catch (error) {
    logger.debug({ error }, "Git commit failed");
    console.log(source_default.yellow("⚠️  Could not commit changes automatically"));
    console.log(source_default.gray("  You can commit the changes manually later."));
  }
}

