async function interactiveMapping() {
  const rl = readline.createInterface({ input, output });
  const jira = new JiraClient(getJiraClientOptions());
  try {
    console.log(source_default.bold.cyan(`
\uD83D\uDD17 Interactive Assignee Mapping
`));
    console.log(source_default.gray(`Let's map Backlog assignees to Jira user identifiers.
`));
    const backlogUser = await rl.question("Backlog assignee (e.g., @john.doe): ");
    if (!backlogUser || backlogUser.trim() === "") {
      console.log(source_default.yellow("Cancelled"));
      return;
    }
    const cleanBacklogUser = backlogUser.startsWith("@") ? backlogUser.substring(1) : backlogUser;
    console.log(source_default.gray(`
Searching for Jira users (this may take a moment)...
`));
    const users = await jira.searchUsers(cleanBacklogUser);
    if (users.length === 0) {
      console.log(source_default.yellow(`No Jira users found matching "${cleanBacklogUser}"`));
      console.log(source_default.gray(`
You can add the mapping manually with:`));
      console.log(source_default.cyan(`  backlog-jira map-assignees add @${cleanBacklogUser} <jira-user-id>`));
      return;
    }
    console.log(source_default.bold(`Found Jira users:
`));
    users.forEach((user, idx) => {
      console.log(`[${idx + 1}] ${user.displayName} (${user.emailAddress || user.accountId})`);
    });
    console.log("[0] Cancel");
    const choice = await rl.question(`
Select user number: `);
    const idx = Number.parseInt(choice, 10);
    if (idx === 0 || Number.isNaN(idx)) {
      console.log(source_default.yellow("Cancelled"));
      return;
    }
    if (idx < 1 || idx > users.length) {
      console.log(source_default.red("Invalid selection"));
      return;
    }
    const selectedUser = users[idx - 1];
    const jiraUserId = selectedUser.emailAddress || selectedUser.accountId;
    await addMapping(cleanBacklogUser, jiraUserId, { force: false });
  } catch (error) {
    logger.error({ error }, "Interactive mapping failed");
    console.error(source_default.red(`Error: ${error}`));
    throw error;
  } finally {
    rl.close();
    try {
      await jira.close();
    } catch {}
  }
}
