async function push(options = {}) {
  const originalLevel = logger.level;
  if (!options.verbose) {
    logger.level = "error";
  }
  logger.info({ options }, "Starting push operation");
  let fieldMappings;
  try {
    fieldMappings = loadFieldMappings();
  } catch (error) {
    logger.level = originalLevel;
    throw error;
  }
  const store = new FrontmatterStore;
  const backlog = new BacklogClient;
  const jira = new JiraClient(getJiraClientOptions());
  const config = loadConfig2();
  const projectKey = config.jira?.projectKey;
  const issueType = config.jira?.issueType || "Task";
  if (!projectKey) {
    throw new Error("Jira project key not configured in .backlog-jira/config.json");
  }
  const result = {
    success: true,
    pushed: [],
    failed: [],
    skipped: []
  };
  try {
    const taskIds = await getTaskIds2(options, backlog, jira, store);
    logger.info({ count: taskIds.length }, "Tasks to process");
    const batchSize = 10;
    for (let i = 0;i < taskIds.length; i += batchSize) {
      const batch = taskIds.slice(i, i + batchSize);
      const promises = batch.map(async (taskId) => {
        try {
          await pushTask(taskId, {
            store,
            backlog,
            jira,
            projectKey,
            issueType,
            fieldMappings,
            force: options.force || false,
            dryRun: options.dryRun || false
          });
          result.pushed.push(taskId);
          logger.info({ taskId }, "Successfully pushed task");
        } catch (error) {
          const errorMsg = error instanceof Error ? error.message : String(error);
          result.failed.push({
            taskId,
            error: errorMsg,
            ...error instanceof MappedFieldPushError ? { mappedFieldError: error } : {}
          });
          logger.error({ taskId, error: errorMsg }, "Failed to push task");
          result.success = false;
        }
      });
      await Promise.all(promises);
    }
    store.logOperation("push", null, null, result.success ? "success" : "partial", JSON.stringify(result));
  } finally {
    try {
      await jira.close();
    } catch (e) {}
    store.close();
    logger.level = originalLevel;
  }
  logger.info({ result }, "Push operation completed");
  return result;
}
async function getTaskIds2(options, backlog, jira, store) {
  if (options.taskIds && options.taskIds.length > 0) {
    return options.taskIds;
  }
  if (options.all) {
    const mappings = store.getAllMappings();
    return Array.from(mappings.keys());
  }
  const mappings = store.getAllMappings();
  const needsPush = [];
  for (const [taskId, jiraKey] of mappings) {
    try {
      const task = await backlog.getTask(taskId);
      const issue = await jira.getIssue(jiraKey);
      const backlogPayload = normalizeBacklogTask(task);
      const jiraPayload = normalizeJiraIssue(issue);
      const backlogHash = computeHash(backlogPayload);
      const jiraHash = computeHash(jiraPayload);
      const snapshots = store.getSnapshots(taskId);
      const state = classifySyncState(backlogHash, jiraHash, snapshots.backlog, snapshots.jira, { backlog: backlogPayload, jira: jiraPayload });
      if (state.state === "NeedsPush") {
        needsPush.push(taskId);
      }
    } catch (error) {
      logger.warn({ taskId, jiraKey, error }, "Failed to check sync state");
    }
  }
  return needsPush;
}
async function pushTask(taskId, context) {
  const {
    store,
    backlog,
    jira,
    projectKey,
    issueType,
    fieldMappings,
    force,
    dryRun
  } = context;
  const overridden = getOverriddenCoreFields(fieldMappings);
  const task = await backlog.getTask(taskId);
  const backlogPayload = normalizeBacklogTask(task);
  const backlogHash = computeHash(backlogPayload);
  const mapping = store.getMapping(taskId);
  if (mapping) {
    const issue = await jira.getIssue(mapping.jiraKey);
    const jiraPayload = normalizeJiraIssue(issue);
    const jiraHash = computeHash(jiraPayload);
    if (!force) {
      const snapshots = store.getSnapshots(taskId);
      const state = classifySyncState(backlogHash, jiraHash, snapshots.backlog, snapshots.jira, { backlog: backlogPayload, jira: jiraPayload });
      if (state.state === "Conflict") {
        throw new Error(`Conflict detected. Use --force to override or run 'backlog-jira sync' to resolve`);
      }
    }
    const updates = await buildJiraUpdates(task, issue, jira, projectKey, overridden);
    const mappedUpdates = buildMappedJiraFields(readTaskFrontmatter(taskId), issue, fieldMappings);
    if (dryRun) {
      logger.info({
        taskId,
        jiraKey: mapping.jiraKey,
        updates,
        mappedFields: mappedUpdates.fields
      }, "DRY RUN: Would update Jira issue");
    } else {
      const failures = await updateIssueWithMappedFields(jira, mapping.jiraKey, updates.fields, mappedUpdates);
      if (updates.transition) {
        await jira.transitionIssue(mapping.jiraKey, updates.transition.id, {
          comment: updates.transition.comment
        });
      }
      const updatedIssue = await jira.getIssue(mapping.jiraKey);
      if (failures.length > 0) {
        recordPartialPush(store, taskId, task, updatedIssue, failures, fieldMappings);
        throw new MappedFieldPushError(mapping.jiraKey, failures);
      }
      recordSyncedSnapshots(store, taskId, {
        backlog: normalizeBacklogTask(task),
        jira: normalizeJiraIssue(updatedIssue)
      }, "backlog", fieldMappings);
      store.updateSyncState(taskId, {
        lastSyncAt: new Date().toISOString()
      });
      try {
        const filePath = getTaskFilePath(taskId);
        const jiraUrl = process.env.JIRA_URL ? `${process.env.JIRA_URL}/browse/${mapping.jiraKey}` : undefined;
        updateJiraMetadata(filePath, {
          jiraKey: mapping.jiraKey,
          jiraUrl,
          jiraLastSync: new Date().toISOString(),
          jiraSyncState: "InSync"
        });
        logger.debug({ taskId, jiraKey: mapping.jiraKey }, "Updated frontmatter with Jira metadata");
      } catch (error) {
        logger.error({ taskId, error }, "Failed to update frontmatter, but push was successful");
      }
    }
  } else {
    const mappedUpdates = buildMappedJiraFields(readTaskFrontmatter(taskId), null, fieldMappings);
    if (dryRun) {
      logger.info({ taskId, projectKey, issueType, mappedFields: mappedUpdates.fields }, "DRY RUN: Would create new Jira issue");
    } else {
      const descriptionWithAc = task.acceptanceCriteria ? mergeDescriptionWithAc(task.description || "", task.acceptanceCriteria, task.implementationPlan, task.implementationNotes) : task.description;
      const mappedAssignee = task.assignee ? mapBacklogAssigneeToJira(task.assignee) : undefined;
      if (task.assignee && !mappedAssignee) {
        logger.warn({ taskId, assignee: task.assignee }, "No Jira user mapping found for Backlog assignee. Configure mapping with: backlog-jira map-assignees add");
      }
      const { issue, failures } = await createIssueWithMappedFields(jira, projectKey, issueType, task.title, {
        description: descriptionWithAc,
        assignee: mappedAssignee || undefined,
        priority: task.priority && !overridden.has("priority") ? mapBacklogPriorityToJira(task.priority) : undefined,
        labels: overridden.has("labels") ? undefined : task.labels
      }, mappedUpdates);
      store.addMapping(taskId, issue.key);
      if (failures.length > 0) {
        const createdIssue = await jira.getIssue(issue.key);
        recordPartialPush(store, taskId, task, createdIssue, failures, fieldMappings);
      } else {
        store.setSnapshot(taskId, "backlog", backlogHash, normalizeBacklogTask(task));
        store.setSnapshot(taskId, "jira", backlogHash, normalizeJiraIssue(issue));
      }
      store.updateSyncState(taskId, {
        lastSyncAt: new Date().toISOString()
      });
      try {
        const filePath = getTaskFilePath(taskId);
        const jiraUrl = process.env.JIRA_URL ? `${process.env.JIRA_URL}/browse/${issue.key}` : undefined;
        updateJiraMetadata(filePath, {
          jiraKey: issue.key,
          jiraUrl,
          jiraLastSync: new Date().toISOString(),
          jiraSyncState: failures.length > 0 ? "NeedsPush" : "InSync"
        });
        logger.debug({ taskId, jiraKey: issue.key }, "Updated frontmatter with Jira metadata for new issue");
      } catch (error) {
        logger.error({ taskId, error }, "Failed to update frontmatter, but push was successful");
      }
      if (failures.length > 0) {
        throw new MappedFieldPushError(issue.key, failures);
      }
      logger.info({ taskId, jiraKey: issue.key }, "Created new Jira issue");
    }
  }
}
async function buildJiraUpdates(task, currentIssue, jiraClient, projectKey, overridden = new Set) {
  const fields = {};
  if (task.title !== currentIssue.summary) {
    fields.summary = task.title;
  }
  const taskDescriptionWithAc = task.acceptanceCriteria ? mergeDescriptionWithAc(task.description || "", task.acceptanceCriteria, task.implementationPlan, task.implementationNotes) : task.description || "";
  const currentJiraDescClean = stripAcceptanceCriteriaFromDescription(currentIssue.description || "");
  const taskDescClean = stripAcceptanceCriteriaFromDescription(task.description || "");
  if (taskDescClean !== currentJiraDescClean || JSON.stringify(task.acceptanceCriteria) !== JSON.stringify(normalizeBacklogTask(task).acceptanceCriteria)) {
    fields.description = taskDescriptionWithAc;
    logger.debug({ taskId: task.id }, "Updating Jira description with AC");
  }
  if (task.assignee) {
    const mappedAssignee = mapBacklogAssigneeToJira(task.assignee);
    if (!mappedAssignee) {
      logger.warn({ taskId: task.id, assignee: task.assignee }, "No Jira user mapping found for Backlog assignee. Configure mapping with: backlog-jira map-assignees add");
    } else if (mappedAssignee !== currentIssue.assignee) {
      fields.assignee = mappedAssignee;
      logger.debug({
        taskId: task.id,
        backlogAssignee: task.assignee,
        jiraAssignee: mappedAssignee
      }, "Mapped Backlog assignee to Jira user");
    }
  }
  if (task.priority && !overridden.has("priority")) {
    const mappedPriority = mapBacklogPriorityToJira(task.priority);
    if (mappedPriority && mappedPriority !== currentIssue.priority) {
      fields.priority = mappedPriority;
      logger.debug({
        taskId: task.id,
        backlogPriority: task.priority,
        jiraPriority: mappedPriority
      }, "Mapped Backlog priority to Jira priority");
    }
  }
  if (!overridden.has("labels") && task.labels && JSON.stringify(task.labels) !== JSON.stringify(currentIssue.labels)) {
    fields.labels = task.labels;
  }
  let transition;
  if (task.status && task.status !== currentIssue.status) {
    const transitionResult = await findTransitionForStatus(jiraClient, currentIssue.key, task.status, projectKey);
    if (transitionResult.success && transitionResult.transitionId) {
      transition = {
        id: transitionResult.transitionId,
        comment: `Status updated from Backlog: ${currentIssue.status} → ${task.status}`
      };
      logger.info({
        taskId: task.id,
        from: currentIssue.status,
        to: task.status,
        transitionId: transitionResult.transitionId,
        transitionName: transitionResult.transitionName
      }, "Status transition found");
    } else {
      logger.warn({
        taskId: task.id,
        from: currentIssue.status,
        to: task.status,
        error: transitionResult.error
      }, "Failed to find status transition");
    }
  }
  return { fields, transition };
}
function loadConfig2() {
  try {
    const configPath = join15(process.cwd(), ".backlog-jira", "config.json");
    const content = readFileSync15(configPath, "utf-8");
    return JSON.parse(content);
  } catch (error) {
    logger.warn({ error }, "Failed to load config, using defaults");
    return {};
  }
}

// src/commands/status.ts
async function getStatus(options) {
  const store = new FrontmatterStore;
  const backlog = new BacklogClient;
  const jira = new JiraClient(getJiraClientOptions());
  try {
    const mappings = store.getAllMappings();
    if (mappings.size === 0) {
      console.log("No task mappings found. Run 'backlog-jira map' first.");
      return;
    }
    console.log(`\uD83D\uDCCA Checking sync status for ${mappings.size} mapped tasks...
`);
    const statuses = [];
    for (const [taskId, jiraKey] of mappings.entries()) {
      try {
        const task = await backlog.getTask(taskId);
        const issue = await jira.getIssue(jiraKey);
        const backlogPayload = normalizeBacklogTask(task);
        const jiraPayload = normalizeJiraIssue(issue);
        const currentBacklogHash = computeHash(backlogPayload);
        const currentJiraHash = computeHash(jiraPayload);
        const snapshots = store.getSnapshots(taskId);
        const stateResult = classifySyncState(currentBacklogHash, currentJiraHash, snapshots.backlog, snapshots.jira, { backlog: backlogPayload, jira: jiraPayload });
        let changedFields;
        if (stateResult.state !== "InSync" && snapshots.backlog && snapshots.jira) {
          const baseBacklogPayload = JSON.parse(snapshots.backlog.payload);
          const baseJiraPayload = JSON.parse(snapshots.jira.payload);
          if (stateResult.state === "NeedsPush") {
            changedFields = comparePayloads(baseBacklogPayload, backlogPayload);
          } else if (stateResult.state === "NeedsPull") {
            changedFields = comparePayloads(baseJiraPayload, jiraPayload);
          } else if (stateResult.state === "Conflict") {
            const backlogChanges = comparePayloads(baseBacklogPayload, backlogPayload);
            const jiraChanges = comparePayloads(baseJiraPayload, jiraPayload);
            changedFields = [...new Set([...backlogChanges, ...jiraChanges])];
          }
        }
        statuses.push({
          taskId,
          taskTitle: task.title,
          jiraKey,
          syncState: stateResult.state,
          backlogHash: stateResult.backlogHash,
          jiraHash: stateResult.jiraHash,
          changedFields
        });
      } catch (error) {
        logger.error({ error, taskId, jiraKey }, "Failed to get status");
        statuses.push({
          taskId,
          taskTitle: "Error",
          jiraKey,
          syncState: "Unknown",
          backlogHash: "",
          jiraHash: ""
        });
      }
    }
    let filteredStatuses = statuses;
    if (options.grep) {
      const grepLower = options.grep.toLowerCase();
      filteredStatuses = statuses.filter((s) => s.syncState.toLowerCase().includes(grepLower) || s.taskId.toLowerCase().includes(grepLower));
    }
    if (options.json) {
      console.log(JSON.stringify(filteredStatuses, null, 2));
    } else {
      displayStatusTable(filteredStatuses);
    }
    if (!options.json) {
      const counts = {
        InSync: statuses.filter((s) => s.syncState === "InSync").length,
        NeedsPush: statuses.filter((s) => s.syncState === "NeedsPush").length,
        NeedsPull: statuses.filter((s) => s.syncState === "NeedsPull").length,
        Conflict: statuses.filter((s) => s.syncState === "Conflict").length,
        Unknown: statuses.filter((s) => s.syncState === "Unknown").length
      };
      console.log(`
\uD83D\uDCC8 Summary:`);
      console.log(`   ✅ InSync: ${counts.InSync}`);
      console.log(`   ⬆️  NeedsPush: ${counts.NeedsPush}`);
      console.log(`   ⬇️  NeedsPull: ${counts.NeedsPull}`);
      console.log(`   ⚠️  Conflict: ${counts.Conflict}`);
      console.log(`   ❓ Unknown: ${counts.Unknown}`);
      if (counts.Conflict > 0) {
        console.log(`
\uD83D\uDCA1 Tip: Use 'backlog-jira resolve' to handle conflicts`);
      }
    }
  } finally {
    store.close();
    await jira.close();
  }
}
function displayStatusTable(statuses) {
  console.log("╔═══════════════╦════════════╦═══════════════╦════════════════════════════════╗");
  console.log("║ Task ID       ║ Jira Key   ║ Sync State    ║ Changed Fields                 ║");
  console.log("╠═══════════════╬════════════╬═══════════════╬════════════════════════════════╣");
  for (const status of statuses) {
    const stateIcon = getStateIcon(status.syncState);
    const stateStr = `${stateIcon} ${status.syncState}`.padEnd(13);
    const fieldsStr = (status.changedFields?.join(", ") || "").slice(0, 30).padEnd(30);
    console.log(`║ ${status.taskId.padEnd(13)} ║ ${status.jiraKey.padEnd(10)} ║ ${stateStr} ║ ${fieldsStr} ║`);
  }
  console.log("╚═══════════════╩════════════╩═══════════════╩════════════════════════════════╝");
}
function getStateIcon(state) {
  switch (state) {
    case "InSync":
      return "✅";
    case "NeedsPush":
      return "⬆️ ";
    case "NeedsPull":
      return "⬇️ ";
    case "Conflict":
      return "⚠️ ";
    case "Unknown":
      return "❓";
    default:
      return "  ";
  }
}
function registerStatusCommand(program) {
  program.command("status").description("Show sync status of mapped tasks").option("--json", "Output in JSON format").option("--grep <pattern>", "Filter results by sync state or task ID").action(async (options) => {
    try {
      await getStatus(options);
      process.exit(0);
    } catch (error) {
      logger.error({ error }, "Status command failed");
      console.error(`Error: ${error}`);
      process.exit(1);
    }
  });
}

